#include "code_scan.h"
#include "reporter.h"
static const char*sev_str[]={"INFO","WARNING","ERROR","CRITICAL"};
static const char*cat_str[]={"Syntax","Security","Memory","Type","Performance","Concurrency","Quality","Preprocessor","Buffer","Portability","Style","LangSpecific"};
static const char*severity_colors[]={"\033[36m","\033[33m","\033[31m","\033[31;1m"};
static const char*color_reset="\033[0m";
static const char*color_bold="\033[1m";
static const char*color_red="\033[31m";
static const char*color_green="\033[32m";
static const char*color_yellow="\033[33m";
static const char*color_blue="\033[34m";
static const char*color_magenta="\033[35m";
static const char*color_cyan="\033[36m";
static const char*color_white="\033[37m";
ReportData*reporter_compute(Project*p){ReportData*rd=calloc(1,sizeof(ReportData));if(!rd)return NULL;rd->total_files=p->total_files;rd->total_lines=p->total_lines;for(int i=0;i<p->nfiles;i++){SourceFile*f=p->files[i];if(!f)continue;for(int j=0;j<f->nissues;j++){Issue*iss=&f->issues[j];rd->total_issues++;switch(iss->sev){case SEV_CRITICAL:rd->total_critical++;break;case SEV_ERROR:rd->total_error++;break;case SEV_WARNING:rd->total_warning++;break;case SEV_INFO:rd->total_info++;break;}switch(iss->cat){case CAT_SYNTAX:rd->total_syntax++;break;case CAT_SECURITY:rd->total_security++;break;case CAT_MEMORY:rd->total_memory++;break;case CAT_TYPE:rd->total_type++;break;case CAT_PERFORMANCE:rd->total_perf++;break;case CAT_CONCURRENCY:rd->total_concurrency++;break;case CAT_QUALITY:rd->total_quality++;break;case CAT_BUFFER:rd->total_buf++;break;}}}rd->score=100.0;rd->security_score=100.0;rd->quality_score=100.0;if(rd->total_issues>0){double per_issue=100.0/(double)(rd->total_issues+1);rd->score-=per_issue*(double)rd->total_critical*3.0;rd->score-=per_issue*(double)rd->total_error*2.0;rd->score-=per_issue*(double)rd->total_warning;rd->score-=per_issue*(double)rd->total_info*0.5;if(rd->score<0)rd->score=0;if(rd->total_security>0){rd->security_score=100.0-per_issue*(double)rd->total_security*5.0;if(rd->security_score<0)rd->security_score=0;}if(rd->total_quality>0){rd->quality_score=100.0-per_issue*(double)rd->total_quality*2.0;if(rd->quality_score<0)rd->quality_score=0;}}return rd;}
void reporter_header(ReportData*rd,Project*p,Buffer*b){time_t now=time(NULL);struct tm*tm_info=localtime(&now);char time_buf[64];strftime(time_buf,sizeof(time_buf),"%Y-%m-%d %H:%M:%S",tm_info);buffer_append_str(b,"\n");buffer_append_str(b,"╔══════════════════════════════════════════════════════════════════╗\n");buffer_append_str(b,"║              C O D E - S C A N   S T A T I C   A N A L Y S I S            ║\n");buffer_append_str(b,"║          S T A T I C   A N A L Y S I S   R E P O R T                 ║\n");buffer_append_str(b,"╚══════════════════════════════════════════════════════════════════╝\n");buffer_append_str(b,"\n");buffer_printf(b,"  Report Generated : %s\n",time_buf);buffer_printf(b,"  Code-Scan Version   : %s\n",CODE_SCAN_VERSION);buffer_printf(b,"  Project Name    : %s\n",p->project_name);buffer_printf(b,"  Project Root    : %s\n",p->root_path);buffer_printf(b,"  Analysis Time   : %.3f seconds\n",p->analysis_time);buffer_printf(b,"  Check Level     : %d\n",p->check_level);buffer_append_str(b,"\n");buffer_printf(b,"  Languages Detected : ");int lang_shown=0;int lang_counts[29]={0};for(int i=0;i<p->nfiles;i++){if(p->files[i]){Language l=p->files[i]->lang;if(l>=0&&l<29)lang_counts[l]++;}}for(int i=0;i<29;i++){if(lang_counts[i]>0){if(lang_shown)buffer_append_str(b,", ");buffer_printf(b,"%s (%d)",lang_str[i],lang_counts[i]);lang_shown=1;}}if(!lang_shown)buffer_append_str(b,"(none)");buffer_append_str(b,"\n");buffer_append_str(b,"\n");buffer_append_str(b,"  ────────────────────────────────────────────────────────────────────\n");buffer_append_str(b,"\n");}
void reporter_summary(ReportData*rd,Project*p,Buffer*b){buffer_append_str(b,"\n--- S U M M A R Y ---\n\n");buffer_append_str(b,"  ╔══════════════════════════════════════════════════════════════╗\n");buffer_append_str(b,"  ║                    ANALYSIS SUMMARY                         ║\n");buffer_append_str(b,"  ╚══════════════════════════════════════════════════════════════╝\n");buffer_printf(b,"    Files Analyzed    : %d\n",rd->total_files);buffer_printf(b,"    Total Lines       : %d\n",rd->total_lines);buffer_printf(b,"    Total Issues      : %d\n",rd->total_issues);buffer_append_str(b,"\n");buffer_printf(b,"    CRITICAL          : %d\n",rd->total_critical);buffer_printf(b,"    ERROR             : %d\n",rd->total_error);buffer_printf(b,"    WARNING           : %d\n",rd->total_warning);buffer_printf(b,"    INFO              : %d\n",rd->total_info);buffer_append_str(b,"\n");buffer_printf(b,"    Security Score    : %.1f/100\n",rd->security_score);buffer_printf(b,"    Quality Score     : %.1f/100\n",rd->quality_score);buffer_printf(b,"    Overall Score     : %.1f/100\n",rd->score);buffer_append_str(b,"\n");if(rd->score>=90)buffer_append_str(b,"    Rating            : EXCELLENT\n");else if(rd->score>=75)buffer_append_str(b,"    Rating            : GOOD\n");else if(rd->score>=60)buffer_append_str(b,"    Rating            : FAIR\n");else if(rd->score>=40)buffer_append_str(b,"    Rating            : POOR\n");else buffer_append_str(b,"    Rating            : CRITICAL\n");buffer_append_str(b,"\n");}
void reporter_breakdown(ReportData*rd,Buffer*b){buffer_append_str(b,"\n--- B R E A K D O W N   B Y   C A T E G O R Y ---\n\n");buffer_append_str(b,"  Category                Count     Severity Distribution\n");buffer_append_str(b,"  ─────────────────────── ───────   ──────────────────────\n");buffer_printf(b,"  %-23s %5d     ",cat_str[0],rd->total_syntax);for(int i=0;i<rd->total_syntax&&i<20;i++)buffer_append_str(b,"█");buffer_append_str(b,"\n");buffer_printf(b,"  %-23s %5d     ",cat_str[1],rd->total_security);for(int i=0;i<rd->total_security&&i<20;i++)buffer_append_str(b,"█");buffer_append_str(b,"\n");buffer_printf(b,"  %-23s %5d     ",cat_str[2],rd->total_memory);for(int i=0;i<rd->total_memory&&i<20;i++)buffer_append_str(b,"█");buffer_append_str(b,"\n");buffer_printf(b,"  %-23s %5d     ",cat_str[3],rd->total_type);for(int i=0;i<rd->total_type&&i<20;i++)buffer_append_str(b,"█");buffer_append_str(b,"\n");buffer_printf(b,"  %-23s %5d     ",cat_str[4],rd->total_perf);for(int i=0;i<rd->total_perf&&i<20;i++)buffer_append_str(b,"█");buffer_append_str(b,"\n");buffer_printf(b,"  %-23s %5d     ",cat_str[5],rd->total_concurrency);for(int i=0;i<rd->total_concurrency&&i<20;i++)buffer_append_str(b,"█");buffer_append_str(b,"\n");buffer_printf(b,"  %-23s %5d     ",cat_str[6],rd->total_quality);for(int i=0;i<rd->total_quality&&i<20;i++)buffer_append_str(b,"█");buffer_append_str(b,"\n");buffer_printf(b,"  %-23s %5d     ",cat_str[7],rd->total_buf);for(int i=0;i<rd->total_buf&&i<20;i++)buffer_append_str(b,"█");buffer_append_str(b,"\n");buffer_append_str(b,"\n");}
void reporter_issues(ReportData*rd,Project*p,Buffer*b,int max_issues){buffer_append_str(b,"\n--- I S S U E   D E T A I L S ---\n\n");int count=0;for(int i=0;i<p->nfiles&&(max_issues<=0||count<max_issues);i++){SourceFile*f=p->files[i];if(!f)continue;for(int j=0;j<f->nissues&&(max_issues<=0||count<max_issues);j++){Issue*iss=&f->issues[j];count++;buffer_append_str(b,"┌─────────────────────────────────────────────────────────────────────────┐\n");buffer_printf(b,"│ [%s] %-4s │ %-30s │\n",sev_str[iss->sev],color_red,iss->sev>=SEV_ERROR?color_red:iss->sev==SEV_WARNING?color_yellow:"");buffer_printf(b,"│ ID: CS-%05d                                               │\n",iss->code);buffer_printf(b,"│ File: %-70s │\n",iss->loc.file);buffer_printf(b,"│ Line: %-6d  Col: %-4d                                         │\n",iss->loc.line,iss->loc.col);buffer_printf(b,"│ Severity: %-8s   Category: %-15s              │\n",sev_str[iss->sev],cat_str[iss->cat]);buffer_printf(b,"│ Code: CS-%04d                                                 │\n",iss->code);buffer_append_str(b,"├─────────────────────────────────────────────────────────────────────────┤\n");buffer_printf(b,"│ Message: %-68s │\n",iss->msg);if(iss->suggestion[0])buffer_printf(b,"│ Suggestion: %-65s │\n",iss->suggestion);if(iss->context[0])buffer_printf(b,"│ Context: %-67s │\n",iss->context);buffer_append_str(b,"└─────────────────────────────────────────────────────────────────────────┘\n");buffer_append_str(b,"\n");}}}
void reporter_score(ReportData*rd,Buffer*b){buffer_append_str(b,"\n--- S C O R E   C A R D ---\n\n");buffer_append_str(b,"  ╔════════════════════════════════════════════╗\n");buffer_append_str(b,"  ║              SCORE CARD                   ║\n");buffer_append_str(b,"  ╚════════════════════════════════════════════╝\n");buffer_append_str(b,"\n");buffer_append_str(b,"          ╔═══════════════════════════════╗\n");buffer_printf(b,"          ║  Overall Score: %6.1f / 100  ║\n",rd->score);buffer_append_str(b,"          ╚═══════════════════════════════╝\n");buffer_append_str(b,"\n");int bar_width=50;int fill=(int)(rd->score/100.0*bar_width);if(fill<0)fill=0;if(fill>bar_width)fill=bar_width;buffer_append_str(b,"  Score: [");buffer_append_str(b,color_green);for(int i=0;i<bar_width;i++){if(i<fill){if(rd->score>=75)buffer_append_str(b,"▓");else if(rd->score>=50)buffer_append_str(b,"▒");else buffer_append_str(b,"░");}else buffer_append_str(b," ");}buffer_append_str(b,"]\n");buffer_append_str(b,"\n");int sec_fill=(int)(rd->security_score/100.0*bar_width);if(sec_fill<0)sec_fill=0;if(sec_fill>bar_width)sec_fill=bar_width;buffer_append_str(b,"  Security: [");buffer_append_str(b,color_red);for(int i=0;i<bar_width;i++)buffer_append_str(b,i<sec_fill?"▓":" ");buffer_append_str(b,"]\n");int qual_fill=(int)(rd->quality_score/100.0*bar_width);buffer_append_str(b,"  Quality:  [");buffer_append_str(b,color_blue);for(int i=0;i<bar_width;i++)buffer_append_str(b,i<qual_fill?"▓":" ");buffer_append_str(b,"]\n");buffer_append_str(b,"\n");}
void reporter_text_report(ReportData*rd,Project*p,Buffer*b){reporter_header(rd,p,b);reporter_summary(rd,p,b);reporter_breakdown(rd,b);reporter_issues(rd,p,b,100);reporter_score(rd,b);buffer_append_str(b,"\n--- E N D   O F   R E P O R T ---\n");buffer_append_str(b,"\n");buffer_append_str(b,"  This report was generated by Code-Scan Static Analyzer v");buffer_append_str(b,CODE_SCAN_VERSION);buffer_append_str(b,"\n");buffer_append_str(b,"  Copyright (C) 2026 XPDevs. All rights reserved.\n");buffer_append_str(b,"\n");buffer_append_str(b,"  Code-Scan is a comprehensive static analysis tool for C/C++ codebases.\n");buffer_append_str(b,"  For more information, visit: https://github.com/code-scan/analyzer\n");buffer_append_str(b,"\n");}
void reporter_json_report(ReportData*rd,Project*p,Buffer*b){buffer_append_str(b,"{\n");buffer_printf(b,"  \"tool\": \"Code-Scan Static Analyzer\",\n");buffer_printf(b,"  \"version\": \"%s\",\n",CODE_SCAN_VERSION);time_t now=time(NULL);struct tm*tm_info=localtime(&now);char tb[64];strftime(tb,sizeof(tb),"%Y-%m-%dT%H:%M:%S",tm_info);buffer_printf(b,"  \"timestamp\": \"%s\",\n",tb);buffer_printf(b,"  \"project\": \"%s\",\n",p->project_name);buffer_printf(b,"  \"root\": \"%s\",\n",p->root_path);buffer_printf(b,"  \"summary\": {\n");buffer_printf(b,"    \"files\": %d,\n",rd->total_files);buffer_printf(b,"    \"lines\": %d,\n",rd->total_lines);buffer_printf(b,"    \"total_issues\": %d,\n",rd->total_issues);buffer_printf(b,"    \"critical\": %d,\n",rd->total_critical);buffer_printf(b,"    \"errors\": %d,\n",rd->total_error);buffer_printf(b,"    \"warnings\": %d,\n",rd->total_warning);buffer_printf(b,"    \"info\": %d,\n",rd->total_info);buffer_printf(b,"    \"score\": %.1f,\n",rd->score);buffer_printf(b,"    \"security_score\": %.1f,\n",rd->security_score);buffer_printf(b,"    \"quality_score\": %.1f\n",rd->quality_score);buffer_append_str(b,"  },\n");buffer_append_str(b,"  \"issues\": [\n");int first=1;for(int i=0;i<p->nfiles;i++){SourceFile*f=p->files[i];if(!f)continue;for(int j=0;j<f->nissues;j++){Issue*iss=&f->issues[j];if(!first)buffer_append_str(b,",\n");first=0;buffer_append_str(b,"    {\n");buffer_printf(b,"      \"id\": \"CS-%05d\",\n",iss->code);buffer_printf(b,"      \"file\": \"%s\",\n",iss->loc.file);buffer_printf(b,"      \"line\": %d,\n",iss->loc.line);buffer_printf(b,"      \"col\": %d,\n",iss->loc.col);buffer_printf(b,"      \"severity\": \"%s\",\n",sev_str[iss->sev]);buffer_printf(b,"      \"category\": \"%s\",\n",cat_str[iss->cat]);buffer_printf(b,"      \"code\": %d,\n",iss->code);buffer_printf(b,"      \"message\": \"%s\"\n",iss->msg);buffer_append_str(b,"    }");}}buffer_append_str(b,"\n  ],\n");buffer_printf(b,"  \"copyright\": \"Copyright (C) 2026 XPDevs. All rights reserved.\"\n}\n");}
void reporter_html_report(ReportData*rd,Project*p,Buffer*b){buffer_append_str(b,"<!DOCTYPE html><html><head><meta charset='UTF-8'><title>Code-Scan Analysis Report - ");buffer_append_str(b,p->project_name);buffer_append_str(b,"</title><style>body{font-family:'Courier New',monospace;background:#1a1a2e;color:#e0e0e0;margin:40px;line-height:1.6}.header{border:2px solid #e94560;padding:20px;margin-bottom:30px;background:#16213e}.score-card{border:2px solid #0f3460;padding:15px;margin:15px 0;background:#16213e}.critical{color:#ff4757}.error{color:#ff6348}.warning{color:#ffa502}.info{color:#70a1ff}.issue-box{border:1px solid #333;padding:10px;margin:10px 0;background:#0f3460}.severity-tag{display:inline-block;padding:2px 8px;border-radius:3px;font-weight:bold}.sev-critical{background:#ff4757;color:#fff}.sev-error{background:#ff6348;color:#fff}.sev-warning{background:#ffa502;color:#000}.sev-info{background:#70a1ff;color:#000}table{width:100%;border-collapse:collapse;margin:15px 0}th,td{padding:8px;text-align:left;border-bottom:1px solid #333}th{background:#0f3460}.bar{height:20px;background:#2d3436;border-radius:10px;overflow:hidden;margin:5px 0}.bar-fill{height:100%;transition:width 0.3s}.bar-green{background:#00b894}.bar-red{background:#d63031}.bar-blue{background:#0984e3}pre{background:#0a0a1a;padding:10px;overflow-x:auto}</style></head><body>");buffer_printf(b,"<div class='header'><h1>Code-Scan Static Analysis Report</h1><h2>Project: %s</h2>",p->project_name);time_t now=time(NULL);struct tm*tm_info=localtime(&now);char tb[64];strftime(tb,sizeof(tb),"%Y-%m-%d %H:%M:%S",tm_info);buffer_printf(b,"<p>Generated: %s | Version: %s</p><p>Copyright (C) 2026 XPDevs. All rights reserved.</p></div>",tb,CODE_SCAN_VERSION);buffer_printf(b,"<div class='score-card'><h2>Summary</h2><table><tr><th>Metric</th><th>Value</th></tr><tr><td>Files Analyzed</td><td>%d</td></tr><tr><td>Total Lines</td><td>%d</td></tr><tr><td>Total Issues</td><td>%d</td></tr><tr><td>Critical</td><td class='critical'>%d</td></tr><tr><td>Errors</td><td class='error'>%d</td></tr><tr><td>Warnings</td><td class='warning'>%d</td></tr><tr><td>Info</td><td class='info'>%d</td></tr></table></div>",rd->total_files,rd->total_lines,rd->total_issues,rd->total_critical,rd->total_error,rd->total_warning,rd->total_info);buffer_printf(b,"<div class='score-card'><h2>Scores</h2><p>Overall: <strong>%.1f/100</strong></p><div class='bar'><div class='bar-fill bar-green' style='width:%.0f%%'></div></div><p>Security: <strong>%.1f/100</strong></p><div class='bar'><div class='bar-fill bar-red' style='width:%.0f%%'></div></div><p>Quality: <strong>%.1f/100</strong></p><div class='bar'><div class='bar-fill bar-blue' style='width:%.0f%%'></div></div></div>",rd->score,rd->score,rd->security_score,rd->security_score,rd->quality_score,rd->quality_score);buffer_append_str(b,"<div class='score-card'><h2>Issues</h2>");for(int i=0;i<p->nfiles;i++){SourceFile*f=p->files[i];if(!f)continue;for(int j=0;j<f->nissues;j++){Issue*iss=&f->issues[j];buffer_printf(b,"<div class='issue-box'><span class='severity-tag sev-%s'>%s</span> <strong>CS-%05d</strong> ",sev_str[iss->sev],sev_str[iss->sev],iss->code);buffer_printf(b,"<span class='%s'>%s</span>",sev_str[iss->sev]==SEV_CRITICAL?"critical":sev_str[iss->sev]==SEV_ERROR?"error":sev_str[iss->sev]==SEV_WARNING?"warning":"info",cat_str[iss->cat]);buffer_printf(b,"<p><strong>%s</strong> at line %d, col %d</p>",iss->loc.file,iss->loc.line,iss->loc.col);buffer_printf(b,"<pre>%s</pre>",iss->msg);if(iss->suggestion[0])buffer_printf(b,"<p><em>Suggestion: %s</em></p>",iss->suggestion);buffer_append_str(b,"</div>");}}buffer_append_str(b,"</div></body></html>");}
char*reporter_generate(Project*p,ReportConfig*cfg,int*out_len){ReportData*rd=reporter_compute(p);if(!rd){if(out_len)*out_len=0;return NULL;}Buffer*buf=buffer_new(65536);if(cfg->format==1)reporter_json_report(rd,p,buf);else if(cfg->format==2)reporter_html_report(rd,p,buf);else reporter_text_report(rd,p,buf);free(rd);char*result=buffer_detach(buf);if(out_len)*out_len=(int)strlen(result);return result;}
